"""Find course material copied into a practice project before it is committed.

Usage: python docs/learning/check-course-overlap.py projects/<project>
Exit 1 when a project file is byte-identical to a file under courses/, or
shares RUN or more consecutive lines with one of the same suffix.
"""
import subprocess
import sys
from pathlib import Path

RUN = 15  # the threshold approved for public repos
# Generated by Spring Initializr / Gradle, or third-party with its own licence.
SKIP_NAMES = {"gradlew", "gradlew.bat", "gradle-wrapper.properties",
              ".gitignore", ".gitattributes"}
SKIP_ENDS = (".jar", ".min.css", ".min.js")
ROOT = Path(__file__).resolve().parents[2]


def lines(data: bytes):
    """Trimmed non-blank lines without package/import; None for binary."""
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return None
    out = [s.strip() for s in text.splitlines()]
    return [s for s in out if s and not s.startswith(("package ", "import "))]


def longest_run(a, b):
    """Length of the longest run of consecutive equal lines in a and b."""
    where = {}
    for j, s in enumerate(b):
        where.setdefault(s, []).append(j)
    best, prev = 0, {}
    for s in a:
        cur = {j: prev.get(j - 1, 0) + 1 for j in where.get(s, ())}
        best = max(best, max(cur.values(), default=0))
        prev = cur
    return best


def main(project):
    project = Path(project).resolve()
    names = subprocess.run(
        ["git", "-C", str(project), "ls-files", "-co", "--exclude-standard"],
        capture_output=True, text=True, check=True).stdout.splitlines()
    course = {}  # suffix -> [(path, bytes, lines)]
    for p in (ROOT / "courses").rglob("*"):
        if (p.is_file() and "code" in p.parts
                and not {"build", "bin"} & set(p.parts)):
            data = p.read_bytes()
            course.setdefault(p.suffix, []).append((p, data, lines(data)))
    hits = []
    for name in names:
        f = project / name
        if f.name in SKIP_NAMES or name.endswith(SKIP_ENDS) or not f.is_file():
            continue
        data = f.read_bytes()
        mine = lines(data)
        best = (0, "")  # one line per project file: its worst match
        for p, cdata, theirs in course.get(f.suffix, ()):
            rel = p.relative_to(ROOT).as_posix()
            if data == cdata:
                best = (float("inf"), f"{name}: identical to {rel}")
                break
            if mine and theirs and (n := longest_run(mine, theirs)) > best[0]:
                best = (n, f"{name}: {n} consecutive lines match {rel}")
        if best[0] >= RUN:
            hits.append(best[1])
    print("\n".join(hits) or "course overlap: 0")
    return 1 if hits else 0


if __name__ == "__main__":
    assert longest_run(list("xabcy"), list("pabcq")) == 3
    assert longest_run(list("ab"), list("cd")) == 0
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    sys.exit(main(sys.argv[1]))
